     const live=HAIR_DYNAMICS.style===model.style&&HAIR_DYNAMICS.frame&&Math.abs(HAIR_DYNAMICS.frame.cx-cx)<.01&&Math.abs(HAIR_DYNAMICS.frame.rot-rot)<.01&&Math.abs(HAIR_DYNAMICS.frame.yaw-yaw)<.001;
