          const tap=Math.sin(loop*Math.PI*2);
          const sway=Math.cos(loop*Math.PI*2);
          const ldx=sway*1.2, ldy=tap*4.0;
          p.wrist_L[0]+=ldx; p.wrist_L[1]+=ldy;
