      dizzy: { id: 'dizzy', label: 'Dizzy', duration: 1900, face: 'tapSquint' },
      laugh: { id: 'laugh', label: 'Laugh', duration: 2000, face: 'tapPlayful' },
      joy: { id: 'joy', label: 'Jump for joy', duration: 1500, face: 'success' }
