        const h = q[`hand_${s}_center`];
        const d = Math.hypot(h[0] - hc[0], h[1] - hc[1]);
        if (d < 1 || !characterCovers(q, h, 0, 44)) continue;
        const w = smooth5(clamp((q.neck[1] - 40 - h[1]) / 80)) * smooth5(clamp((d - (q.head_radius + 40)) / 60));
        if (w <= 0) continue;
        let k = 0;
