      if (!CLOCK.reduced && !walkActive && !mv && !posed && !soulOwnsArms) applyLifeGestures(q, cur, now);
      if (pz) { q.footScale = pz.pose.footScale; q.walkFootAngle = pz.pose.walkFootAngle; q.transplanted = pz.pose.transplanted; }
